#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_SESSIONS 64
#define TOKEN_LEN 32
#define MAX_MSG_SIZE 4096

typedef struct {
    uint8_t version;
    uint8_t msg_type;
    int16_t payload_len;  /* signed 16-bit length field */
    uint32_t session_id;
    uint8_t hmac[32];
} __attribute__((packed)) msg_header_t;

typedef struct {
    int active;
    uint32_t session_id;
    uint8_t auth_token[TOKEN_LEN];
    uint8_t session_key[32];
    int privilege_level;
    time_t created;
} session_t;

static session_t sessions[MAX_SESSIONS];
static pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

/* Constant-time comparison for HMAC verification */
static int secure_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    volatile uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

/* Compute HMAC-SHA256 (simplified for demonstration) */
static void compute_hmac(const uint8_t *key, size_t key_len,
                         const uint8_t *data, size_t data_len,
                         uint8_t *out) {
    /* In production, use a real HMAC implementation */
    uint8_t pad[64];
    memset(pad, 0x36, sizeof(pad));
    for (size_t i = 0; i < key_len && i < 64; i++)
        pad[i] ^= key[i];
    /* Simplified: just XOR fold for demo purposes */
    memset(out, 0, 32);
    for (size_t i = 0; i < data_len; i++)
        out[i % 32] ^= data[i] ^ pad[i % 64];
}

static session_t* find_session(uint32_t session_id) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (sessions[i].active && sessions[i].session_id == session_id)
            return &sessions[i];
    }
    return NULL;
}

static int verify_message_integrity(const msg_header_t *hdr,
                                     const uint8_t *payload,
                                     const session_t *sess) {
    uint8_t computed_hmac[32];
    /* HMAC covers header (minus hmac field) + payload */
    size_t header_data_len = sizeof(msg_header_t) - 32;
    size_t total_len = header_data_len + (size_t)hdr->payload_len;

    uint8_t *hmac_input = malloc(total_len);
    if (!hmac_input) return 0;

    memcpy(hmac_input, hdr, header_data_len);
    memcpy(hmac_input + header_data_len, payload, hdr->payload_len);

    compute_hmac(sess->session_key, 32, hmac_input, total_len, computed_hmac);
    free(hmac_input);

    return secure_compare(computed_hmac, hdr->hmac, 32);
}

/* Process authenticated data update command */
static int process_data_update(const uint8_t *payload, int16_t len,
                                session_t *sess) {
    if (sess->privilege_level < 2) {
        return -1;  /* Insufficient privileges */
    }

    /* Validate payload structure: first 4 bytes = offset, rest = data */
    if (len < 4) return -1;

    uint32_t offset = *(uint32_t*)payload;
    const uint8_t *data = payload + 4;
    int16_t data_len = len - 4;

    /* Security check: ensure we don't write beyond session token bounds */
    if (offset + data_len > TOKEN_LEN) {
        return -1;  /* Would overflow token buffer */
    }

    /* Update the session's auth token with new data */
    memcpy(sess->auth_token + offset, data, data_len);
    return 0;
}

/* Main message handler */
static void handle_message(int client_fd) {
    uint8_t recv_buf[MAX_MSG_SIZE];
    msg_header_t *hdr;
    uint8_t *payload;

    ssize_t bytes = recv(client_fd, recv_buf, MAX_MSG_SIZE, 0);
    if (bytes < (ssize_t)sizeof(msg_header_t)) {
        return;
    }

    hdr = (msg_header_t*)recv_buf;
    payload = recv_buf + sizeof(msg_header_t);

    /* Version check */
    if (hdr->version != 2) {
        return;
    }

    /* Validate payload length against received data */
    if (hdr->payload_len > (int16_t)(bytes - sizeof(msg_header_t))) {
        return;  /* Claimed payload exceeds received data */
    }

    /* Length sanity check - reject oversized messages */
    if (hdr->payload_len > MAX_MSG_SIZE) {
        return;
    }

    pthread_mutex_lock(&session_lock);
    session_t *sess = find_session(hdr->session_id);
    if (!sess) {
        pthread_mutex_unlock(&session_lock);
        return;
    }

    /* Verify HMAC before processing */
    if (!verify_message_integrity(hdr, payload, sess)) {
        pthread_mutex_unlock(&session_lock);
        return;
    }

    /* Dispatch based on message type */
    int result = -1;
    switch (hdr->msg_type) {
        case 0x01:  /* Data update */
            result = process_data_update(payload, hdr->payload_len, sess);
            break;
        case 0x02:  /* Query */
            /* Read-only operation, safe */
            result = 0;
            break;
        default:
            break;
    }

    pthread_mutex_unlock(&session_lock);

    /* Send response */
    uint8_t resp = (result == 0) ? 0x01 : 0x00;
    send(client_fd, &resp, 1, 0);
}

static void* client_thread(void *arg) {
    int fd = *(int*)arg;
    free(arg);
    handle_message(fd);
    close(fd);
    return NULL;
}

int main(int argc, char *argv[]) {
    int server_fd;
    struct sockaddr_in addr;

    memset(sessions, 0, sizeof(sessions));
    /* Create a test session for demonstration */
    sessions[0].active = 1;
    sessions[0].session_id = 0x41414141;
    memset(sessions[0].session_key, 0x42, 32);
    sessions[0].privilege_level = 3;
    sessions[0].created = time(NULL);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) return 1;

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(9090);

    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0)
        return 1;
    if (listen(server_fd, 16) < 0)
        return 1;

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
        if (client_fd < 0) continue;

        int *fd_ptr = malloc(sizeof(int));
        if (!fd_ptr) { close(client_fd); continue; }
        *fd_ptr = client_fd;

        pthread_t tid;
        if (pthread_create(&tid, NULL, client_thread, fd_ptr) != 0) {
            free(fd_ptr);
            close(client_fd);
        } else {
            pthread_detach(tid);
        }
    }

    return 0;
}
